SELECT OWNER,OBJECT_NAME,OBJECT_TYPE,STATUS FROM ALL_OBJECTS WHERE OWNER='SIDDA' AND (OBJECT_NAME IN ('LGL_AGT_RUN_A','LGL_AGT_REC_A','LGL_AGT_BODY_A','LGL_EXEC_ST_A') OR OBJECT_NAME LIKE 'LGL_AR01_%' OR OBJECT_NAME LIKE 'LGL_AR02_%' OR OBJECT_NAME LIKE 'LGL_AR03_%') ORDER BY OBJECT_TYPE,OBJECT_NAME
